end
u={'016'=>x('attribute_matching','B','甲、乙、丙各選一張不同顏色的卡：紅、藍、綠。甲不選紅，乙不選綠，丙選藍。誰選紅？'),'017'=>x('square_classification','5','一個 2×2 方格由四個小正方形組成。數出所有 1×1 和 2×2 的正方形，共有幾個？'),'018'=>x('weighted_average_reverse','24','三個數的平均是 16，其中兩個數是 12、12。第三個數是多少？')}
u['016']['prompt']=l('甲、乙、丙各選一張不同顏色的卡：紅、藍、綠。甲不選紅，乙不選綠，丙選藍。誰選紅？','A, B, and C each choose a different card: red, blue, or green. A does not choose red, B does not choose green, and C chooses blue. Who chooses red?','甲、乙、丙各选一张不同颜色的卡：红、蓝、绿。甲不选红，乙不选绿，丙选蓝。谁选红？','A、B、Cは赤・青・緑の異なるカードを1枚ずつ選びます。Aは赤でなく、Bは緑でなく、Cは青です。赤を選ぶのは誰ですか。')
u['016']['answer']=l('答案是乙。','The answer is B.','答案是乙。','答えはBです。')
u['016']['solutionSteps']=l(['丙選藍，剩下紅和綠給甲、乙。','乙不能選綠，所以乙選紅。'],['C chooses blue, leaving red and green for A and B.','B cannot choose green, so B chooses red.'],['丙选蓝，剩下红和绿给甲、乙。','乙不能选绿，所以乙选红。'],['Cは青なので、AとBには赤と緑が残ります。','Bは緑ではないため、Bが赤を選びます。'])
u['017']['prompt']=l('一個 2×2 方格由四個小正方形組成。數出所有 1×1 和 2×2 的正方形，共有幾個？','A 2-by-2 grid is made of four unit squares. Counting all 1-by-1 and 2-by-2 squares, how many squares are there?','一个 2×2 方格由四个小正方形组成。数出所有 1×1 和 2×2 的正方形，共有几个？','2×2の方眼は4つの小正方形からできています。1×1と2×2の正方形をすべて数えると、いくつありますか。')
u['017']['answer']=l('答案是 5。','The answer is 5.','答案是 5。','答えは5です。')
u['017']['solutionSteps']=l(['有四個 1×1 小正方形。','另有一個完整的 2×2 大正方形。','所以共有 4+1=5 個。'],['There are four 1-by-1 unit squares.','There is one complete 2-by-2 square.','Thus there are 4+1=5 squares.'],['有四个 1×1 小正方形。','另有一个完整的 2×2 大正方形。','所以共有 4+1=5 个。'],['1×1の小正方形は4個です。','さらに2×2の大きな正方形が1個あります。','よって4+1=5個です。'])
u['018']['prompt']=l('三個數的平均是 16，其中兩個數是 12、12。第三個數是多少？','The average of three numbers is 16. Two of the numbers are 12 and 12. What is the third number?','三个数的平均是 16，其中两个数是 12、12。第三个数是多少？','3つの数の平均は16で、そのうち2つは12、12です。3つ目の数はいくつですか。')
u['018']['answer']=l('答案是 24。','The answer is 24.','答案是 24。','答えは24です。')
u['018']['solutionSteps']=l(['三個數的總和是 16×3=48。','已知兩個數的和是 12+12=24。','第三個數是 48−24=24。'],['The total of the three numbers is 16×3=48.','The two known numbers total 12+12=24.','The third number is 48−24=24.'],['三个数的总和是 16×3=48。','已知两个数的和是 12+12=24。','第三个数是 48−24=24。'],['3つの数の合計は16×3=48です。','分かっている2つの和は12+12=24です。','3つ目は48−24=24です。'])
p['questions'].each{|q|k=q['id'].split('_').last;q.replace({'id'=>q['id']}.merge(u[k])) if u[k]};File.write('assets/questions/mixed/kangaroo56_foundation.mixed.v1.json',JSON.pretty_generate(p)+"\n")
